def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Simple approach: find first difference and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            # Insert at end
            return ("", s_out[len(s_in):], len(s_in))
        else:
            # Delete from end  
            return (s_in[len(s_out):], "", len(s_out))

    # Look for longest substring match to determine what to replace
    # For now, simple approach - check if we're replacing one character or substring
    old_sub = ""
    new_sub = ""

    # Check if we're inserting
    if len(s_in) < len(s_out):
        # Insertion case
        # Find what was inserted
        for i in range(len(s_out)):
            if i >= len(s_in) or s_in[i] != s_out[i]:
                # Insertion happened at position i
                # Check what's inserted
                insert_start = i
                while insert_start < len(s_out) and (insert_start >= len(s_in) or s_out[insert_start] == s_in[insert_start]):
                    insert_start += 1
                new_sub = s_out[i:insert_start]
                return ("", new_sub, i)

    # Check if we're deleting
    elif len(s_in) > len(s_out):
        # Deletion case
        # Find what was deleted
        for i in range(len(s_in)):
            if i >= len(s_out) or s_in[i] != s_out[i]:
                # Deletion happened at position i
                # Check what was deleted
                delete_end = i
                while delete_end < len(s_in) and (delete_end >= len(s_out) or s_in[delete_end] == s_out[delete_end]):
                    delete_end += 1
                old_sub = s_in[i:delete_end]
                return (old_sub, "", i)

    # Substitution case
    else:
        # Find first differing character
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)

    return ("", "", -1)

